package com.example

import com.example.ExamQuestionHelper.QSpec

object DancingLiveExamMudraClassicalBank1 {
    private const val T = "හස්ත මුද්‍රා විද්‍යාව හා භාරතීය/විදේශීය සම්භාව්‍ය නර්තන"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("භාරතීය නාට්‍ය ශාස්ත්‍රය හා අභිනය දර්පණය අනුව තනි අතින් දක්වන මුද්‍රා හඳුන්වනු ලබන්නේ කුමන නමකින්ද?", "අසංයුත හස්ත මුද්‍රා", "සංයුත හස්ත මුද්‍රා", "නෘත්ත හස්ත මුද්‍රා", "පාද හස්ත මුද්‍රා", "තනි අතින් නිරූපණය කරන හස්ත මුද්‍රා අසංයුත හස්ත ලෙස හැඳින්වේ."),
        q("නන්දිකේශ්වරයන්ගේ 'අභිනය දර්පණ' ග්‍රන්ථයට අනුව අසංයුත හස්ත මුද්‍රා සංඛ්‍යාව කීයද?", "28 කි", "24 කි", "13 කි", "32 කි", "අභිනය දර්පණයෙහි අසංයුත හස්ත මුද්‍රා 28 ක් විස්තර කෙරේ."),
        q("අභිනය දර්පණයට අනුව දෑතම එක්කර දක්වන සංයුත හස්ත මුද්‍රා සංඛ්‍යාව කීයද?", "24 කි", "28 කි", "18 කි", "16 කි", "දෑතේම සුසංයෝගයෙන් නිරූපණය කරන සංයුත හස්ත 24 කි."),
        q("අසංයුත හස්ත මුද්‍රා 28 න් පළමුවැන්න වන සියලු ඇඟිලි දිගු කර මහපටැඟිල්ල නවා තබන මුද්‍රාව කුමක්ද?", "පතක හස්තය", "ත්‍රිපතක හස්තය", "මයුර හස්තය", "ශිඛර හස්තය", "ධජයක හැඩය ගත් පතක හස්තය ආශිර්වාදය, ආරම්භය හා ගංගා දැක්වීමට යෙදේ."),
        q("පතක හස්තයේ සිට වෙදැඟිල්ල නැවීමෙන් සාදනු ලබන හස්ත මුද්‍රාව කුමක්ද?", "ත්‍රිපතක හස්තය", "අර්ධපතක හස්තය", "කර්තරිමුඛ හස්තය", "සූචි හස්තය", "වෙදැඟිල්ල නැවූ විට ත්‍රිපතක හස්තය ලැබෙන අතර එය ඔටුන්න හා ගස නිරූපණය කරයි."),
        q("ත්‍රිපතක හස්තයේ සිට කුඩා ඇඟිල්ලද නැවීමෙන් නිර්මාණය වන මුද්‍රාව කුමක්ද?", "අර්ධපතක හස්තය", "පතක හස්තය", "අරාල හස්තය", "මුෂ්ටි හස්තය", "වෙදැඟිල්ල සහ සුළැඟිල්ල යන දෙකම නැවූ විට අර්ධපතක හස්තය සෑදේ."),
        q("ත්‍රිපතක හස්තයේදී දබරැඟිල්ල සහ මැදැඟිල්ල කතුරක් මෙන් විහිදුවා තබන මුද්‍රාව කුමක්ද?", "කර්තරිමුඛ හස්තය", "මුකුල හස්තය", "කංගුල හස්තය", "සිංහමුඛ හස්තය", "කර්තරිමුඛ මුද්‍රාව ස්ත්‍රී පුරුෂ වෙන්වීම, ඇස් කොණ හා විදුලිය දැක්වීමට යෙදේ."),
        q("වෙදැඟිල්ලේ අග මහපටැඟිල්ලේ අගට ස්පර්ශ කර අනෙක් ඇඟිලි දිගු කරන මුද්‍රාව කුමක්ද?", "මයුර හස්තය", "හංසාස්‍ය හස්තය", "භ්‍රමර හස්තය", "කපිත්ථ හස්තය", "මයුර හස්තය මොනර ගෙල, තිලකය තැබීම හා කේශාලංකරණය දැක්වීමට යොදාගනී."),
        q("පතක හස්තයේ සිට මහපටැඟිල්ල පමණක් පිටතට දිගු කරන අර්ධචන්ද්‍ර හස්තයෙන් නිරූපණය නොවන්නේ කුමක්ද?", "මල් කිනිත්තක් කැඩීම", "අඩ සඳ", "ඉඟටිය", "පූජා භාජනයක් ඇල්ලීම", "අර්ධචන්ද්‍ර මුද්‍රාවෙන් අඩ සඳ, ඉඟටිය හා භාජන ඇල්ලීම ආදිය දැක්වේ."),
        q("පතක හස්තයේදී දබරැඟිල්ල කොක්කක් සේ නවා තබන මුද්‍රාව හඳුන්වන්නේ කුමන නමකින්ද?", "අරාල හස්තය", "ශුකතුණ්ඩ හස්තය", "පද්මකෝෂ හස්තය", "සර්පශීර්ෂ හස්තය", "අරාල හස්තය විෂ පානය කිරීම හා තද සුළඟ දැක්වීමට භාවිත වේ."),
        q("අරාල හස්තයේදී වෙදැඟිල්ලද කොක්කක් සේ නැවූ විට සෑදෙන 'ගිරා හොට' වැනි මුද්‍රාව කුමක්ද?", "ශුකතුණ්ඩ හස්තය", "මෘගශීර්ෂ හස්තය", "චතුර හස්තය", "කපෝත හස්තය", "ශුකතුණ්ඩ යනු ගිරවාගේ හොටයි. එය ඊතලය හා කෝපය දැක්වීමට යොදයි."),
        q("සියලුම ඇඟිලි අල්ල දෙසට තදින් මිට මොළවා මහපටැඟිල්ල ඇඟිලි මත තබන මුද්‍රාව කුමක්ද?", "මුෂ්ටි හස්තය", "ශිඛර හස්තය", "කපිත්ථ හස්තය", "අලපද්ම හස්තය", "මුෂ්ටි මුද්‍රාව ස්ථිර බව, කේශ කලාපය ඇල්ලීම හා පොරබැදීම දැක්වීමට යොදයි."),
        q("මුෂ්ටි හස්තයේ සිට මහපටැඟිල්ල පමණක් ඉහළට ඔසවා තබන මුද්‍රාව කුමක්ද?", "ශිඛර හස්තය", "සූචි හස්තය", "තාම්‍රචූඩ හස්තය", "චන්ද්‍රකලා හස්තය", "ශිඛර හස්තය දුන්න ඇල්ලීම, කඳු මුදුන, පියා හා සැමියා නිරූපණයට යොදයි."),
        q("ශිඛර හස්තයේදී දබරැඟිල්ල මහපටැඟිල්ලේ මුදුනට නවා තබන මුද්‍රාව කුමක්ද?", "කපිත්ථ හස්තය", "භ්‍රමර හස්තය", "මුකුල හස්තය", "පල්ලව හස්තය", "කපිත්ථ මුද්‍රාව ලක්ෂ්මී දේවිය, සරස්වතී දේවිය හා මල් නෙළීම දැක්වීමට යෙදේ."),
        q("මැදැඟිල්ල හා වෙදැඟිල්ල මහපටැඟිල්ලට තබා දබරැඟිල්ල හා සුළැඟිල්ල ඉහළට විහිදුවන මුද්‍රාව කුමක්ද?", "මෘගශීර්ෂ හස්තය", "සිංහමුඛ හස්තය", "කටකාමුඛ හස්තය", "ත්‍රිශූල හස්තය", "මුව හිසේ හැඩය ගත් මෘගශීර්ෂ හස්තය කාන්තාවන්, කපොල් හා දුර සිට කතා කිරීම දැක්වීමට යොදයි."),
        q("දබරැඟිල්ල පමණක් ඉහළට දිගු කර අනෙක් ඇඟිලි මහපටැඟිල්ලෙන් මිට මොළවන මුද්‍රාව කුමක්ද?", "සූචි හස්තය", "පතක හස්තය", "මයුර හස්තය", "කංගුල හස්තය", "සූචි හස්තයෙන් එක, පරබ්‍රහ්ම, සූර්යයා, නගරය සහ තර්ජනය දැක්වේ."),
        q("සූචි හස්තයේදී මහපටැඟිල්ල දිගු කර දබරැඟිල්ලද දිගු කළ විට සෑදෙන 'අඩ සඳ' හැඩැති මුද්‍රාව කුමක්ද?", "චන්ද්‍රකලා හස්තය", "අර්ධචන්ද්‍ර හස්තය", "සර්පශීර්ෂ හස්තය", "තාම්‍රචූඩ හස්තය", "චන්ද්‍රකලා මුද්‍රාව ශිව දෙවියන්ගේ හිස මත ඇති සඳ කලාව දැක්වීමට විශේෂ වේ."),
        q("ඇඟිලි පහම මඳක් නවා මල් කැකුළක් හෝ පොකුරක් මෙන් විවෘතව තබන මුද්‍රාව කුමක්ද?", "පද්මකෝෂ හස්තය", "මුකුල හස්තය", "අලපද්ම හස්තය", "භ්‍රමර හස්තය", "නෙළුම් කැකුළක හැඩැති පද්මකෝෂ හස්තය පලතුරු, මල් කැකුළු හා පූජා දැක්වීමට යොදයි."),
        q("පතක හස්තයේ ඇඟිලි අග මඳක් ඇතුළට නවා නාග පෙනයක් මෙන් තබන මුද්‍රාව කුමක්ද?", "සර්පශීර්ෂ හස්තය", "සිංහමුඛ හස්තය", "කූර්ම හස්තය", "මත්ස්‍ය හස්තය", "සර්පශීර්ෂ මුද්‍රාව නාගයා, සඳුන් ආලේප කිරීම හා ජලය ඉසීම දැක්වීමට භාවිත වේ."),
        q("මැදැඟිල්ල හා වෙදැඟිල්ල මහපටැඟිල්ලට ස්පර්ශ කර දබරැඟිල්ල හා සුළැඟිල්ල නවා තබන මුද්‍රාව කුමක්ද?", "සිංහමුඛ හස්තය", "මෘගශීර්ෂ හස්තය", "මුකුල හස්තය", "කපිත්ථ හස්තය", "සිංහමුඛ හස්තය සිංහයා, හෝම ගින්න හා පවිත්‍ර බව දැක්වීමට යොදාගනී."),
        q("ඇඟිලි පහේම අග්‍ර එකට එක්කර කැකුළු හැඩයට තබන මුද්‍රාව කුමක්ද?", "මුකුල හස්තය", "පද්මකෝෂ හස්තය", "අලපද්ම හස්තය", "හංසාස්‍ය හස්තය", "මුකුල හස්තය ආහාර ගැනීම, ජල ලිලී මල් හා පූජාවන් නිරූපණය කරයි."),
        q("සුළැඟිල්ලේ සිට මහපටැඟිල්ල දක්වා ඇඟිලි පිළිවෙළින් විවෘතව විහිදුවන පිපුණු නෙළුම බඳු මුද්‍රාව කුමක්ද?", "අලපද්ම හස්තය", "පතක හස්තය", "ත්‍රිපතක හස්තය", "සූචි හස්තය", "අලපද්ම හස්තය පිපුණු නෙළුම් මල, පූර්ණ චන්ද්‍රයා හා සුන්දරත්වය දැක්වීමට යොදයි."),
        q("දබරැඟිල්ල හා මහපටැඟිල්ලේ අග්‍ර එක්කර අනෙක් ඇඟිලි තුන විහිදුවන මුද්‍රාව කුමක්ද?", "හංසාස්‍ය හස්තය", "මයුර හස්තය", "භ්‍රමර හස්තය", "කටකාමුඛ හස්තය", "හංසාස්‍ය මුද්‍රාව මුතු ඇමිණීම, ලිවීම, මාල ගෙතීම සහ මෘදු සංවාද දැක්වීමට යොදයි."),
        q("දබරැඟිල්ල නවා මැදැඟිල්ල හා මහපටැඟිල්ල එක්කර තබන මුද්‍රාව කුමක්ද?", "භ්‍රමර හස්තය", "හංසපක්ෂ හස්තය", "සංදංශ හස්තය", "ලාංගුල හස්තය", "භ්‍රමර හස්තය මී මැස්සා, ගිරවා, කන් ඇලීම හා සමගිය දැක්වීමට යොදයි."),
        q("පද්මකෝෂ හස්තයේදී ඇඟිලි එකිනෙක හසුරුවමින් යමක් අල්ලන බව දක්වන මුද්‍රාව කුමක්ද?", "සංදංශ හස්තය", "කපෝත හස්තය", "වරාහ හස්තය", "ගරුඩ හස්තය", "සංදංශ මුද්‍රාව පහන් වැටිය ඇල්ලීම, මල් පූජාව සහ සියුම් දේ ඇල්ලීම දැක්වීමට යොදයි."),
        q("සූචි හස්තයේ දබරැඟිල්ල කොක්කක් සේ නැවූ විට කුකුළු කරමලක් බඳුව සෑදෙන මුද්‍රාව කුමක්ද?", "තාම්‍රචූඩ හස්තය", "ශුකතුණ්ඩ හස්තය", "කටකාවර්ධන හස්තය", "උත්සංග හස්තය", "තාම්‍රචූඩ හස්තය කුකුළා, කොකා සහ පෑන දැක්වීමට නර්තනයේදී භාවිත වේ."),
        q("සංයුත හස්ත මුද්‍රා 24 අතරින් පතක හස්ත දෙක පපුව ඉදිරිපිට එක්කර වැඳීම දක්වන මුද්‍රාව කුමක්ද?", "අංජලී හස්තය", "කපෝත හස්තය", "කර්කට හස්තය", "ස්වස්තික හස්තය", "අංජලී හස්තය දෙවියන්, ගුරුවරුන් සහ ප්‍රේක්ෂකයන්ට ආචාර කිරීමට යෙදේ."),
        q("පතක හස්ත දෙකේ පාර්ශ්ව හා අග්‍ර පමණක් එක්කර මැද කුහරයක් තබන සංයුත හස්තය කුමක්ද?", "කපෝත හස්තය", "අංජලී හස්තය", "පුෂ්පපුට හස්තය", "ඩෝලා හස්තය", "පරවියෙකුගේ හැඩය ගත් කපෝත මුද්‍රාව යටහත් පහත් බව, ගෞරවය හා ප්‍රණාමය දැක්වීමට යොදයි."),
        q("අත් දෙකේම ඇඟිලි එකිනෙක පටලවා තබන සංයුත හස්ත මුද්‍රාව කුමක්ද?", "කර්කට හස්තය", "ගරුඩ හස්තය", "නාගබන්ධ හස්තය", "ඛට්වා හස්තය", "කකුළුවෙකුගේ හැඩැති කර්කට මුද්‍රාව හක්ගෙඩිය පිඹීම හා ඇඟ මැලි කැඩීම දැක්වීමට යොදයි."),
        q("පතක හස්ත දෙක මැණික් කටුව ළඟින් කතිරයක් සේ හරස් කොට තබන සංයුත හස්තය කුමක්ද?", "ස්වස්තික හස්තය", "ශිවලිංග හස්තය", "ශකට හස්තය", "ශංඛ හස්තය", "ස්වස්තික හස්තය කිඹුලා, මංගල සලකුණු හා ආලෝකය දැක්වීමට යොදයි."),
        q("පහළට හෙළන ලද සර්පශීර්ෂ හස්ත දෙක මල් දෝතක් මෙන් පාර්ශ්වයෙන් එක්කරන මුද්‍රාව කුමක්ද?", "පුෂ්පපුට හස්තය", "අංජලී හස්තය", "කූර්ම හස්තය", "උත්සංග හස්තය", "පුෂ්පපුට මුද්‍රාව මල් පූජාව, ආරතිය සහ ජලය පිරිනැමීම දැක්වීමට යෙදේ."),
        q("දෑත් පහළට ලිහිල්ව හෙළා පතක හස්ත කලවා දෙපස රඳවන මුද්‍රාව කුමක්ද?", "ඩෝලා හස්තය", "ලතා හස්තය", "පාශ හස්තය", "කීලක හස්තය", "ඩෝලා හස්තය නර්තනයේ ආරම්භක විවේක ඉරියව්ව දැක්වීමට බහුලව යෙදේ."),
        q("වම් අතේ අර්ධචන්ද්‍ර හස්තය මත දකුණු අතේ ශිඛර හස්තය තබා දක්වන සංයුත හස්තය කුමක්ද?", "ශිවලිංග හස්තය", "ශංඛ හස්තය", "චක්‍ර හස්තය", "බේරුණ්ඩ හස්තය", "ශිවලිංග හස්තය ශිව දෙවියන් වන්දනා කිරීම නිරූපණය කරයි."),
        q("මෘගශීර්ෂ හස්ත දෙක උරහිස් හෝ වැළමිට දෙසට හරවා පපුව මත හරස් කොට තබන මුද්‍රාව කුමක්ද?", "උත්සංග හස්තය", "කටකාවර්ධන හස්තය", "අවහිත්ථ හස්තය", "නිෂධ හස්තය", "උත්සංග මුද්‍රාව වැළඳගැනීම, ලැජ්ජාව හා උණුසුම දැක්වීමට යොදයි."),
        q("අර්ධචන්ද්‍ර හස්ත දෙකේ මහපටැඟිලි පටලවා පියාපත් සේ අනෙක් ඇඟිලි විහිදුවන මුද්‍රාව කුමක්ද?", "ගරුඩ හස්තය", "මත්ස්‍ය හස්තය", "කූර්ම හස්තය", "වරාහ හස්තය", "ගරුඩ හස්තයෙන් රාජාලියා හෝ විෂ්ණු දෙවියන්ගේ වාහනය වන ගරුඩා දැක්වේ."),
        q("පතක හස්ත දෙක එක මත එක තබා මහපටැඟිලි දෙක වරල් මෙන් සොලවන සංයුත මුද්‍රාව කුමක්ද?", "මත්ස්‍ය හස්තය", "කූර්ම හස්තය", "නාගබන්ධ හස්තය", "ශකට හස්තය", "මත්ස්‍ය හස්තය ජලයේ පිහිනන මාළුවෙකු හා මත්ස්‍යාවතාරය නිරූපණය කරයි."),
        q("චක්‍ර හස්තය (අර්ධචන්ද්‍ර හස්ත දෙක අත්ලෙන් හරස් කිරීම) මඟින් ප්‍රධාන වශයෙන් නිරූපණය කරන්නේ කුමක්ද?", "විෂ්ණු දෙවියන්ගේ සුදර්ශන චක්‍රය", "ශිව දෙවියන්ගේ ත්‍රිශූලය", "කතරගම දෙවියන්ගේ වේලය", "බ්‍රහ්මයාගේ වීණාව", "චක්‍ර හස්තය දේව ආයුධයක් වන චක්‍රය හා කරකැවෙන රෝදය දැක්වීමට යොදයි."),
        q("කූර්ම හස්තය මඟින් නිරූපණය කරන සත්වයා කවරෙක්ද?", "ඉබ්බා", "මොනරා", "හංසයා", "මුවා", "චක්‍ර හස්තයේ ඇඟිලි නවා ඉබ්බාගේ කටුව මෙන් තැබීමෙන් කූර්ම හස්තය සෑදේ."),
        q("මෘගශීර්ෂ හස්ත දෙක පිටුපසින් තබා මුහුණට මුහුණ ගැටෙන සේ පෙන්වන වරාහ හස්තයෙන් දැක්වෙන්නේ කුමක්ද?", "වල් ඌරා", "වැදි නායකයා", "සිංහ රජු", "ගවයා", "වරාහ යනු වල් ඌරා හෙවත් විෂ්ණුගේ වරාහ අවතාරය දැක්වීමට යොදන මුද්‍රාවයි."),
        q("සර්පශීර්ෂ හස්ත දෙක මැණික් කටුවෙන් පටලවා ඔසවා තබන සංයුත හස්තය කුමක්ද?", "නාගබන්ධ හස්තය", "ස්වස්තික හස්තය", "කීලක හස්තය", "පාශ හස්තය", "නාගබන්ධ හස්තය නාග යුවළ හා නාග ලෝකය නිරූපණය කිරීමට භාවිත වේ."),
        q("සුළැඟිලි දෙක එකට පටලවා මෘගශීර්ෂ හස්ත දෙක ඉහළට ඔසවන මුද්‍රාව කුමක්ද?", "කීලක හස්තය", "පාශ හස්තය", "ඛට්වා හස්තය", "ශංඛ හස්තය", "කීලක හස්තය ස්නේහය, මිත්‍රත්වය හා ප්‍රේම සම්බන්ධතා දැක්වීමට යොදයි."),
        q("සූචි හස්ත දෙකේ දබරැඟිලි නවා එකිනෙක පටලවා පෙන්වන මුද්‍රාව කුමක්ද?", "පාශ හස්තය", "කර්කට හස්තය", "සංදංශ හස්තය", "වරාහ හස්තය", "පාශ හස්තයෙන් විලංගු, මිතුරන් අතර බැඳීම හා ගැටගැසීම නිරූපණය කෙරේ."),
        q("අර්ථ නිරූපණයකින් තොරව නර්තනයේ අලංකාරය හා තාල රටා සඳහා පමණක් යොදන හස්ත මුද්‍රා වර්ගය කුමක්ද?", "නෘත්ත හස්ත", "අභිනය හස්ත", "සංයුත හස්ත", "භාව හස්ත", "නෘත්ත හස්ත යොදාගනු ලබන්නේ අඩව්, තීර්මානම් හා සුන්දර අංගචලන අලංකාර කිරීමටය."),
        q("දේශීය උඩරට නර්තනයේ 'ගජගා වන්නම' නැටීමේදී ඇතාගේ හොඬවැල හා ගමන දැක්වීමට බහුලව යෙදෙන මුද්‍රාව කුමක්ද?", "කරි හස්තය හෙවත් ඩෝලා හා පතක හස්තය", "මුෂ්ටි හස්තය", "කූර්ම හස්තය", "සූචි හස්තය", "ගජගා වන්නමේදී ඇතාගේ හොඬවැල චලනය කිරීමට කළුහස්ත/ඩෝලා මෙන්ම පතක මුද්‍රා යොදාගනී."),
        q("උඩරට 'හනුමා වන්නම' රංගනයේදී වඳුරෙකුගේ හිස හා පැනීම දැක්වීමට යොදාගන්නා මූලික මුද්‍රාව කුමක්ද?", "මුෂ්ටි හා මෘගශීර්ෂ හස්ත", "පුෂ්පපුට හස්තය", "ශිවලිංග හස්තය", "ගරුඩ හස්තය", "හනුමා වන්නමේ සත්ව ලක්ෂණ දැක්වීමට මුෂ්ටි, මෘගශීර්ෂ සහ ත්‍රිපතක වැනි මුද්‍රා උපයෝගී වේ."),
        q("උඩරට 'මයුර වන්නම' නැටීමේදී මොනරාගේ පිල් කලඹ හා ගෙල නිරූපණය කිරීමට වඩාත් ගැළපෙන මුද්‍රාව කුමක්ද?", "මයුර හස්තය සහ අලපද්ම හස්තය", "කපෝත හස්තය", "ශංඛ හස්තය", "සර්පශීර්ෂ හස්තය", "මොනරාගේ ගෙල මයුර හස්තයෙන්ද විහිදුණු පිල් අලපද්ම හස්තයෙන්ද මනාව දැක්වේ."),
        q("ශ්‍රී ලාංකේය නර්තනයේදී හස්ත මුද්‍රාවල මූලික කාර්යභාරය කුමක්ද?", "අදහස් ප්‍රකාශනය හා සංකේතවත් කිරීම", "බෙර හඬ පාලනය කිරීම", "වේදිකා ආලෝකය සැකසීම", "ඇඳුම් කට්ටලය රඳවා ගැනීම", "වචනයෙන් නොකියන අර්ථ හා හැඟීම් ප්‍රේක්ෂකයාට සන්නිවේදනය කිරීම මුද්‍රාවල අරමුණයි."),
        q("උඩරට නර්තනයේ සාම්ප්‍රදායිකව අත් හැසිරවීම හඳුන්වනු ලබන්නේ කුමන යෙදුමකින්ද?", "අත් මාරු සහ අත් ගමන්", "තත්කාර් පියවර", "කළශම් රංගනය", "චක්කර් කැරකීම", "උඩරට නර්තනයේ දෑත් හා අත්ල කැරකැවීම් අත් ගමන් සහ අත් මාරු ලෙස හැඳින්වේ."),
        q("දකුණු ඉන්දියාවේ තමිල්නාඩු ප්‍රදේශයෙන් බිහිවූ පැරණිතම ශාස්ත්‍රීය නර්තන සම්ප්‍රදාය කුමක්ද?", "භරත නාට්‍යම්", "කථක්", "මණිපුරි", "ඔඩිසි", "භරත නාට්‍යම් දකුණු ඉන්දියාවේ දේවාල දේවදාසි සම්ප්‍රදාය ඇසුරෙන් විකාශනය විය."),
        q("භරත නාට්‍යම් සම්ප්‍රදාය පෙරදී හඳුන්වනු ලැබුවේ කුමන නමකින්ද?", "සදීර් හෙවත් දාසි අට්ටම්", "රාස් ලීලා", "කූත්තු", "තෙරුක්කූත්තු", "දේවාලවල පැවති මෙම නැටුම පෙරදී සදීර් හෙවත් දාසි අට්ටම් ලෙස හැඳින්විණි."),
        q("භරත නාට්‍යම් නර්තන ප්‍රසංගයක මුලින්ම ඉදිරිපත් කරන ආරම්භක පිළිගැනීමේ අංගය කුමක්ද?", "අලාරිප්පු", "තිල්ලානා", "වර්ණම්", "පදම්", "අලාරිප්පු යනු මල් පිපීම යන අරුත ඇතිව ශරීරය රංගනයට සූදානම් කරන ආරම්භක අංගයයි."),
        q("භරත නාට්‍යම් ප්‍රසංගයක අවසාන අංගය ලෙස ඉදිරිපත් කරන වේගවත් නෘත්ත අංගය කුමක්ද?", "තිල්ලානා", "ජතිස්වරම්", "ශබ්දම්", "කෞතුවම්", "තිල්ලානා අංගය සංකීර්ණ ජති, තාල රටා හා මනරම් මූර්තිමත් ඉරියව්වලින් යුක්තය."),
        q("භරත නාට්‍යම් නර්තනයේදී අභිනය සහ නෘත්ත යන දෙකම සම්මිශ්‍රණය වූ ප්‍රධානතම මධ්‍යම අංගය කුමක්ද?", "වර්ණම්", "පුෂ්පාංජලී", "ජාවලි", "ශ්ලෝකම්", "වර්ණම් යනු භරත නාට්‍යම් ප්‍රසංගයක හදවත බඳු දීර්ඝතම හා වැදගත්ම අංගයයි."),
        q("භරත නාට්‍යම් සඳහා භාවිත කරන ප්‍රධානතම ශාස්ත්‍රීය සංගීත සම්ප්‍රදාය කුමක්ද?", "කර්ණාටක සංගීතය", "හින්දුස්ථානි සංගීතය", "බටහිර ඔපෙරා සංගීතය", "සුගම ගී සංගීතය", "භරත නාට්‍යම් රංගනයේදී මෘදංගය, වයලීනය හා වීණාව සහිත කර්ණාටක සංගීතය වාදනය කෙරේ."),
        q("භරත නාට්‍යම් නැටුමේදී තාලය මෙහෙයවන ගුරුවරයා හෙවත් නට්ටුවනාර් අත තබාගෙන සිටින භාණ්ඩය කුමක්ද?", "කයිතාලම් හෙවත් ජල්රා යුගලය", "හොරණෑව", "තම්මැට්ටම", "බටනළාව", "නට්ටුවනාර් කුඩා ලෝහ තාලම්පට යුගලයක් වාදනය කරමින් සොල්කට්ටු උච්චාරණය කරයි."),
        q("භරත නාට්‍යම් නර්තනයේ මූලික අඩ සිට ගැනීමේ ඉරියව්ව හඳුන්වන්නේ කුමන නමකින්ද?", "අරමණ්ඩි", "මුරුමණ්ඩි", "සමපාද", "මූලි මණ්ඩිය", "දෙපා පිටතට හරවා දණහිස් නමා සිටින අරමණ්ඩි ඉරියව්ව අපේ මණ්ඩියට සමාන වේ."),
        q("භරත නාට්‍යම් හිදී 'අඩවු' යනු කුමක්ද?", "තාලයකට අනුව සිදු කරන මූලික පියවර හා ශරීර චලන ඒකක", "නර්තන ඇඳුමේ ආභරණයක්", "වේදිකාවේ පහන් තබන ආසනයක්", "භාව ගායනයේ කොටසක්", "අඩවු යනු භරත නාට්‍යම් සම්ප්‍රදායේ පදනම සකසන මූලික චලන සමූහයයි."),
        q("භරත නාට්‍යම් නැටුම් කලාව නූතන වේදිකාවට ගෙන ඒමට පුරෝගාමී වූ විශිෂ්ට ශිල්පිනිය කවුද?", "රුක්මණී දේවි අරුන්ඩේල්", "සරෝජිනී නායිදු", "ලතා මංගේෂ්කර්", "මීරා බායි", "රුක්මණී දේවි අරුන්ඩේල් කලාක්ෂේත්‍ර ආයතනය පිහිටුවා භරත නාට්‍යම් ලොව පුරා ප්‍රචලිත කළාය."),
        q("උතුරු ඉන්දියාවේ බිහිවූ හින්දු හා මෝගල් සංස්කෘතික ආභාසය ලත් ශාස්ත්‍රීය නර්තනය කුමක්ද?", "කථක් නර්තනය", "මෝහිනීඅට්ටම්", "කුචිපුඩි", "සත්ත්‍රියා", "කථක් යනු කතන්දර කීමේ කලාවෙන් බිහිවී රාජ සභාවල දියුණු වූ නර්තන සම්ප්‍රදායයි."),
        q("'කථක්' යන සංස්කෘත වචනයේ නිවැරදි අර්ථය කුමක්ද?", "කතාව හෝ කතා කියන්නා", "වේගවත් කැරකීම", "දේව පූජාව", "සත්ව අනුකරණය", "කථා කහේ සෝ කථක් කහාවේ යන පාඨය අනුව කතා පවසන්නා යන අරුතින් කථක් බිහිවිය."),
        q("කථක් නර්තනයේ විශේෂ ලක්ෂණයක් වන එකම තැන සිට වේගයෙන් කැරකීම හඳුන්වනු ලබන්නේ කෙසේද?", "චක්කර්", "අඩවු", "තාණ්ඩව", "ලස්ය", "කථක් ශිල්පීන් තාලයට අනුව සිදු කරන අඛණ්ඩ කැරකීම් චක්කර් ලෙස හැඳින්වේ."),
        q("කථක් නැටුමේදී දෙපයේ බැඳි ගෙජ්ජිවලින් පාද පොළොවට ගසමින් රිද්මය මැවීම හඳුන්වන්නේ කුමන නමකින්ද?", "තත්කාර්", "අලාරිප්පු", "කලශම්", "තිරනොට්ටු", "තත්කාර් යනු කථක් නර්තනයේ පාද චලන තාක්ෂණයයි."),
        q("කථක් නර්තන සම්ප්‍රදාය සඳහා යොදාගන්නා ප්‍රධානතම අවනද්ධ වාද්‍ය භාණ්ඩ මොනවාද?", "තබ්ලාව සහ පඛවාජ්", "ගැටබෙරය සහ යක්බෙරය", "චෙන්ඩා සහ මද්දලම්", "ඩෝල්කිය සහ රබාන", "හින්දුස්ථානි සංගීතය සමඟ තබ්ලාව හෝ පඛවාජය කථක් නර්තනයට වාදනය කෙරේ."),
        q("කථක් නර්තනයේ ප්‍රධාන ගුරු කුල හෙවත් ඝරානා තුන මොනවාද?", "ජයිපූර්, ලක්නව් සහ බරණැස්", "තන්ජෝර්, මදුරෙයි සහ කේරළ", "මහනුවර, මාතර සහ රත්නපුර", "දිල්ලි, මුම්බායි සහ කොල්කටා", "ජයිපූර් ඝරානාව වීර හා පාද චලනයටත් ලක්නව් ඝරානාව භාව අභිනයටත් ප්‍රසිද්ධය."),
        q("දකුණු ඉන්දියාවේ කේරළ ප්‍රාන්තයේ බිහිවූ ප්‍රසිද්ධ නර්තන නාට්‍ය සම්ප්‍රදාය කුමක්ද?", "කථකලි", "ඔඩිසි", "මණිපුරි", "භරත නාට්‍යම්", "කථකලි යනු විචිත්‍ර මුහුණු සැරසිලි හා දීර්ඝ රාත්‍රී නාට්‍යමය රංගනයන්ගෙන් යුත් කලාවකි."),
        q("කථකලි රංගනයේදී වීර, ශිෂ්ට හා දේව චරිත සඳහා මුහුණේ ආලේප කරන ප්‍රධාන වර්ණ සැරසිල්ල කුමක්ද?", "පච්ච හෙවත් කොළ වර්ණය", "කරි හෙවත් කළු වර්ණය", "තාඩි හෙවත් රතු වර්ණය", "රන්වන් හෙවත් කහ වර්ණය", "සාත්වික වීර චරිත වන රාම, ක්‍රිෂ්ණා ආදීන්ට කොළ පැහැති පච්ච වේෂ නිරූපණය යොදයි."),
        q("කථකලි නැටුමේදී දුෂ්ට හා රෞද්‍ර රාක්ෂස චරිත දැක්වීමට භාවිත කරන වේෂ නිරූපණ වර්ගය කුමක්ද?", "කත්ති සහ තාඩි", "පච්ච සහ මිනුක්කු", "ශුද්ධ මණ්ඩි", "ලස්ය වේෂය", "කත්ති හා රතු රැවුල සහිත තාඩි වේෂය රාවණා වැනි ආඩම්බර හා රෞද්‍ර චරිතවලට යෙදේ."),
        q("කථකලි නර්තනයේදී චරිතයක ඇසේ ගැටියක් ලෙස 'චුන්දපූවු' ඇටයක් තබා ඇස් රතු කරන්නේ කුමක් සඳහාද?", "භාව හා රස ප්‍රකාශනය තීව්‍ර කිරීමට", "ඇස් පෙනීම අඩු කිරීමට", "නින්ද යාම වැළැක්වීමට", "හිස් වැස්ම රඳවා ගැනීමට", "රතු වූ ඇස් කථකලි ශිල්පියාගේ නේත්‍රාභිනය ප්‍රේක්ෂකයාට ඉතා තියුණු ලෙස දිස්වීමට උපකාරී වේ."),
        q("කථකලි නැටුමේදී රංගනය ආරම්භයට පෙර චරිත හඳුන්වා දෙන තිර රෙද්ද පිටුපසින් කරන නැටුම කුමක්ද?", "තිරනොට්ටු", "අලාරිප්පු", "චක්කර්", "ගති භේද", "තිරශීලාව අල්ලාගෙන ප්‍රධාන චරිත හිස් වැස්ම හා ඇස් චලන පෙන්වමින් ඉදිරියට පැමිණේ."),
        q("කථකලි නර්තනයේ ප්‍රධානතම ඝෝෂාකාරී අවනද්ධ වාද්‍ය භාණ්ඩ දෙක මොනවාද?", "චෙන්ඩා සහ මද්දලම්", "තබ්ලාව සහ ඩෝල්කිය", "ගැටබෙරය සහ තම්මැට්ටම", "උඩැක්කිය සහ රබාන", "කේරළයේ චෙන්ඩා බෙරය හා මද්දලම් වාදනය කථකලි නාට්‍යයේ ශබ්ද ප්‍රබලතාව සපයයි."),
        q("ඊසානදිග ඉන්දියාවේ මණිපූර් ප්‍රාන්තයේ බිහිවූ මෘදු හා ලාලිත්‍යමය ශාස්ත්‍රීය නර්තනය කුමක්ද?", "මණිපුරි", "කථකලි", "කුචිපුඩි", "ඔඩිසි", "මණිපුරි නර්තනය ලස්ය ගුණයෙන් පිරි ඉතා මෘදු, තරංගාකාර චලනවලින් සමන්විතය."),
        q("මණිපුරි නර්තනයේදී බහුලව නිරූපණය කෙරෙන ප්‍රධාන භක්තිමය තේමාව කුමක්ද?", "රාධා සහ ක්‍රිෂ්ණාගේ රාස් ලීලා පුවත", "දුර්ගා දේවියගේ යුද්ධය", "පඬුවස්දෙව් රජුගේ කතාව", "චෝල රජවරුන්ගේ ජයග්‍රහණ", "වෛෂ්ණව භක්ති සම්ප්‍රදාය මත පදනම්ව රාස් ලීලා හා ලයි හරෝබා නැටුම් මෙහි ප්‍රධාන වේ."),
        q("මණිපුරි නැටුමේදී කාන්තාවන් අඳින ඉතා පළල් වටකුරු පැහැදිලි රංග වස්ත්‍රය හඳුන්වන්නේ කුමන නමකින්ද?", "කුමිල්", "පෝතෝයි", "වෙස් කට්ටලය", "ඔසරිය", "කුමිල් නමැති දෘඪ බෙර ආකාර සාය මණිපුරි නැටුමට අනන්‍ය සුන්දරත්වයක් ගෙන දෙයි."),
        q("මණිපුරි නර්තනයට වාදනය කරන දෙපැත්තම ගසන සුවිශේෂී බෙරය කුමක්ද?", "පුංග්", "මෘදංගය", "පඛවාජ්", "යක්බෙරය", "පුංග් වාදකයෝ බෙරය කරේ එල්ලාගෙන ඉතා වේගවත් නර්තන රටා ඉදිරිපත් කරති."),
        q("ඉන්දියාවේ ඔඩිෂා ප්‍රාන්තයෙන් බිහිවූ කෝණාර්ක් හිරු දෙවොලේ ප්‍රතිමා මූර්ති සිහිගන්වන ශාස්ත්‍රීය නැටුම කුමක්ද?", "ඔඩිසි", "කථක්", "භරත නාට්‍යම්", "මණිපුරි", "ඔඩිසි නර්තනය ප්‍රතිමාමය ත්‍රිභංග ඉරියව් සඳහා ඉතා ප්‍රසිද්ධියක් උසුලයි."),
        q("ඔඩිසි නර්තනයේ ශරීරය හිස, කඳ සහ උකුළ යන ස්ථාන තුනෙන් නවා සිටින සුප්‍රසිද්ධ ඉරියව්ව කුමක්ද?", "ත්‍රිභංග ඉරියව්ව", "චතුරශ්‍ර ඉරියව්ව", "සමපාද ඉරියව්ව", "මණ්ඩි ඉරියව්ව", "ත්‍රිභංග යනු ශරීරයේ වංගු තුනක් ඇතිවන ඉතා ලාලිත්‍යමය මූර්ති ඉරියව්වයි."),
        q("ආන්ද්‍ර ප්‍රදේශයේ කුචේලපුරම් ගමේ බිහිවී පිත්තල තැටියක ගැටිය මත සිට නටන අංගයක් සහිත නැටුම කුමක්ද?", "කුචිපුඩි", "ඔඩිසි", "මෝහිනීඅට්ටම්", "සත්ත්‍රියා", "කුචිපුඩි නැටුමේ තරංගම් අංගයේදී නැට්ටුවා පිත්තල තැටිය මත සිට තාලයට නටයි."),
        q("කේරළයේ කාන්තාවන් පමණක් ඉදිරිපත් කරන මෘදු ලස්ය ගුණැති ශාස්ත්‍රීය නර්තන සම්ප්‍රදාය කුමක්ද?", "මෝහිනීඅට්ටම්", "කථකලි", "තෙයියම්", "කථක්", "මෝහිනීඅට්ටම් සම්ප්‍රදායේ සුදු හා රන්වන් පැහැති කසාවු සාරිය ප්‍රධාන ඇඳුම වේ."),
        q("අසෑම් ප්‍රාන්තයේ වෛෂ්ණව ආරාම ඇසුරෙන් ශංකරදේවයන් විසින් හඳුන්වා දුන් ශාස්ත්‍රීය නර්තන සම්ප්‍රදාය කුමක්ද?", "සත්ත්‍රියා", "කුචිපුඩි", "මණිපුරි", "ඔඩිසි", "සත්ත්‍රියා නර්තනය ඉන්දියාවේ සම්භාව්‍ය නර්තන අට අතරට පසුව ඇතුළත් වූ සම්ප්‍රදායකි."),
        q("භාරතීය හා ශ්‍රී ලාංකේය නර්තන සම්ප්‍රදායන් අතර දක්නට ලැබෙන ප්‍රධාන සමානකමක් වන්නේ කුමක්ද?", "භූමියට ගරු කිරීමේ මූලික මණ්ඩි ඉරියව්ව", "තබ්ලා වාදනය පමණක් භාවිතය", "චක්කර් කැරකීම් පමණක් භාවිතය", "සැහැල්ලු සපත්තු පැළඳීම", "දෙරටේම සම්භාව්‍ය නර්තන දෙපා නවා භූමිය සමඟ සම්බන්ධ වන මණ්ඩි හෙවත් අරමණ්ඩි ඉරියව් මත ගොඩනැගේ."),
        q("උඩරට නර්තනය හා භරත නාට්‍යම් අතර කැපී පෙනෙන ප්‍රධාන වෙනස්කම කුමක්ද?", "උඩරට නැටුමේදී ගීත ගයමින් නැටීම සහ වේගවත් පිනුම් යෙදීම", "උඩරට නැටුමේදී ගෙජ්ජි නොබැඳීම", "භරත නාට්‍යම් හි අත් චලන නොමැති වීම", "භරත නාට්‍යම් හි තාල භාවිත නොකිරීම", "උඩරට නර්තන ශිල්පියා තනිව වන්නම් ගයමින් නටන නමුත් භරත නාට්‍යම් හි පසුබිම් ගායකයෝ සිටිති."),
        q("ජපානයේ සම්ප්‍රදායික වේදිකා නර්තන නාට්‍ය කලාවන් දෙක හඳුන්වනු ලබන්නේ කුමන නම්වලින්ද?", "නෝ සහ කබුකි", "කථක් සහ කථකලි", "බැලේ සහ ටැන්ගෝ", "හුලා සහ සම්බා", "නෝ සම්භාව්‍ය වෙස්මුහුණු රංගනයක් වන අතර කබුකි විචිත්‍ර වේෂ නිරූපණ සහිත ජනප්‍රිය නාට්‍යයකි."),
        q("ඉන්දුනීසියාවේ බාලි හා ජාවා දූපත්වල පැවැත්වෙන ප්‍රසිද්ධ නර්තන නාට්‍ය සම්ප්‍රදායන් මොනවාද?", "කෙචැක්, ලෙගොං සහ බාරොං", "කබුකි සහ බුගාකු", "වෝල්ට්ස් සහ සල්සා", "කථක් සහ ඔඩිසි", "බාලි නැටුම් බොහෝ විට ගැමෙලාන් සංගීතය සමඟ රාමායණ කතා පුවත් නිරූපණය කරයි."),
        q("යුරෝපයේ රාජ සභාවල බිහිවී ඇඟිලි තුඩුවලින් සිට නටන සම්භාව්‍ය බටහිර නර්තන කලාව කුමක්ද?", "බැලේ නර්තනය", "හිප්හොප් නර්තනය", "බ්‍රේක් ඩාන්ස්", "කපිරිඤ්ඤා", "බැලේ නර්තනය ප්‍රංශ හා රුසියානු සම්භාව්‍ය සංගීතය මත පදනම්ව දියුණු වූ වේදිකා නර්තනයකි."),
        q("චීන සම්ප්‍රදායික උත්සව හා අලුත් අවුරුදු සැමරුම්වලදී අනිවාර්යයෙන් දැකිය හැකි සංස්කෘතික නර්තන අංග මොනවාද?", "සිංහ නැටුම සහ මකර නැටුම", "මොනර නැටුම සහ ගජගා නැටුම", "සළුපාලිය සහ තෙල්මේ", "වන්නම් සහ පන්තේරු", "චීන සංස්කෘතියේ සෞභාග්‍යය හා භූත දෝෂ දුරු කිරීම සංකේතවත් කරමින් මකර හා සිංහ නැටුම් පවත්වයි."),
        q("තායිලන්තයේ රාමකියන් කතා පුවත රඟ දක්වන සම්භාව්‍ය වෙස්මුහුණු නර්තන සම්ප්‍රදාය කුමක්ද?", "ඛෝන් නර්තනය", "නෝ නර්තනය", "රාස් ලීලා", "ෆ්ලැමෙන්කෝ", "ඛෝන් නර්තනය ඉන්දීය රාමායණය ඇසුරින් සැකසුණු තායි රාජකීය වෙස්මුහුණු නාට්‍යයකි."),
        q("ශ්‍රී ලංකාවේ පෘතුගීසි ආභාසයෙන් බිහිවූ ජනප්‍රිය සංගීත හා නර්තන ශෛලිය කුමක්ද?", "කපිරිඤ්ඤා හා බයිලා", "ගම්මඩු හා සොකරි", "කෝලම් හා නාඩගම්", "වන්නම් හා කංකාරි", "පෘතුගීසි හා අප්‍රිකානු සංගීත ආභාසයෙන් මෙරට මුහුදුබඩ කපිරිඤ්ඤා නැටුම් බිහිවිය."),
        q("නට්ටුවනාර් විසින් වාදනය කරන පැරණි ගුරුකුල සම්ප්‍රදායන් දෙක හඳුන්වන 'ගුරු ශිෂ්‍ය පරම්පරාව' යනු කුමක්ද?", "ගුරුවරයාගෙන් ශිෂ්‍යයාට සජීවීව ශිල්පය පැවරීම", "පොත්පත්වලින් පමණක් ඉගෙනීම", "රූපවාහිනියෙන් බලා ඉගෙනීම", "සටහන් ලිවීමෙන් පමණක් පුහුණුවීම", "පෙරදිග සම්භාව්‍ය නර්තනයේදී ගුරුවරයා අසල සිට ප්‍රායෝගිකව නර්තනය ප්‍රගුණ කිරීම ප්‍රධාන වේ."),
        q("නර්තන විද්‍යාවේදී 'තාණ්ඩව' යන යෙදුමෙන් හඳුන්වන්නේ කුමන ස්වභාවයේ නර්තනයක්ද?", "ශිව දෙවියන්ට ආවේණික වූ ජවසම්පන්න හා ප්‍රබල නර්තනය", "පාර්වතී දේවියගේ මෘදු නර්තනය", "විහිළු හාස්‍ය නර්තනය", "වෙස්මුහුණු රහිත කතාව", "තාණ්ඩව යනු පෞරුෂත්වය, වේගය හා ජවය ඉස්මතු වන නර්තන ශෛලියයි."),
        q("නර්තන විද්‍යාවේදී 'ලස්ය' යන යෙදුමෙන් අදහස් කෙරෙන්නේ කුමක්ද?", "මෘදු, සුමට හා ලාලිත්‍යමය නර්තන ස්වභාවය", "රෞද්‍ර හා වේගවත් පිනුම්", "තාල රහිත ගමන්", "වේදිකා සැරසිලි", "පාර්වතී දේවිය නියෝජනය කරන මෘදු ස්ත්‍රී ලාලිත්‍ය ගුණය ලස්ය නම් වේ."),
        q("භාරතීය නර්තනයේදී 'නෘත්ත' යන්නෙන් අදහස් කරන නිවැරදි සංකල්පය කුමක්ද?", "අර්ථ ප්‍රකාශනයක් නැති ශුද්ධ රිද්මයානුකූල නර්තනය", "මුහුණේ හැඟීම් ප්‍රකාශනය", "ගීතයේ අර්ථය මුද්‍රාවෙන් පෙන්වීම", "වේදිකා නාට්‍ය දෙබස් කීම", "නෘත්ත යනු තාලය හා ලය මත පදනම් වූ අලංකාර ශරීර චලන පමණි."),
        q("භාරතීය නර්තන ශාස්ත්‍රයේදී 'නෘත්‍ය' යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "භාව හා රස ප්‍රකාශනය සහිත රිද්මයානුකූල නර්තනය", "තාලය පමණක් ගණන් කිරීම", "දෙබස් රහිත සංගීතය", "බෙර වාදනය පමණක් කිරීම", "නෘත්‍යයේදී තාලයට අමතරව අභිනය මගින් කතාවක් හෝ හැඟීමක් ප්‍රකාශ කෙරේ."),
        q("නාට්‍ය ශාස්ත්‍රයේදී 'නාට්‍ය' යන්නට අයත් වන්නේ කුමන අංගවල එකතුවද?", "නෘත්ත, නෘත්‍ය සහ දෙබස්/ගීත සහිත නාටකීය රංගනය", "තනි ශිල්පියෙකුගේ සරඹ පමණක්", "වාද්‍ය භාණ්ඩ වාදනය පමණක්", "චිත්‍ර හා මූර්ති නිර්මාණය", "නාට්‍ය යනු චතුර්විධ අභිනය හා කතා පුවතක් සහිත සම්පූර්ණ රංග කලාවයි."),
        q("භාරතීය නාට්‍ය ශාස්ත්‍රය රචනා කරන ලද මුනිවරයා කවුද?", "භරත මුනිවරයා", "නන්දිකේශ්වරයන්", "පාණිනී මුනිවරයා", "වැල්මීකි මුනිවරයා", "ක්‍රි.පූ. යුගයේ රචිත නාට්‍ය ශාස්ත්‍රය පෙරදිග නර්තන හා නාට්‍ය කලාවේ මූලික පංචම වේදය ලෙස සැලකේ.")
    )
}
